            { "Réévaluer", "Re-evaluate" }, { "Débloquer la sélection", "Unblock selection" }, { "Tout débloquer", "Unblock all" }, { "Premiers réglages", "First-run setup" }, { "Bienvenue", "Welcome" }, { "Vérification", "Check" }, { "Apprentissage", "Learning" }, { "Qui prévenir", "Who to notify" }, { "Réponses automatiques", "Automatic responses" }, { "PREMIERS RÉGLAGES", "FIRST-RUN SETUP" }, { "EXPOSITION À SURVEILLER", "EXPOSURE TO WATCH" }, { "Pourquoi", "Why" }, { "Appareils", "Devices" }, { "Serveurs DHCP", "DHCP servers" }, { "Redirections UPnP", "UPnP redirections" }, { "Répondeurs", "Responders" }, { "Processus inconnu pour cet élément.", "Unknown process for this item." }, { "Chemin du programme inconnu pour cet élément.", "Unknown program path for this item." }, { "Tuer le processus {0} (PID {1}) ?", "Kill the process {0} (PID {1})?" }, { "Tuer {0} (PID {1}) et tous les processus qu'il a lancés ?", "Kill {0} (PID {1}) and every process it started?" }, { "Suspendre {0} (PID {1}) ? Il restera figé jusqu'à ce que vous le repreniez ou le tuiez.", "Suspend {0} (PID {1})? It will stay frozen until you resume or kill it." }, { "Reprendre {0} (PID {1}) ?", "Resume {0} (PID {1})?" }, { "Arrêter le programme et déplacer le fichier en quarantaine ?", "Stop the program and move the file to quarantine?" }, { "Couper ce programme du réseau (entrant et sortant) ?", "Cut this program off the network (incoming and outgoing)?" }, { "réponse", "response" }, { "Rediriger {0} vers 127.0.0.1 dans le fichier hosts ?", "Redirect {0} to 127.0.0.1 in the hosts file?" }, { "Les connexions en cours vers {0} seront coupées.", "Current connections to {0} will be cut." }, { "Bloquer au pare-feu toutes les connexions sortantes vers {0} ?", "Block every outgoing connection to {0} at the firewall?" }, { "Attention : une même IP peut servir à plusieurs sites (Cloudflare, Google…). La bloquer peut casser d'autres services.", "Careful: one IP address can serve several sites (Cloudflare, Google…). Blocking it may break other services." }, { "Retirer tous les blocages deR4Tizer (fichier hosts et pare-feu) ?", "Remove every deR4Tizer block (hosts file and firewall)?" }, { "Restaurer ce fichier dans le dossier de deR4Tizer (C:\\ProgramData\\deR4Tizer\\restaurations) plutôt qu'à son emplacement d'origine ?", "Restore this file to the deR4Tizer folder (C:\\ProgramData\\deR4Tizer\\restaurations) rather than to its original location?" }, { "Remettre ce fichier à son emplacement d'origine ?", "Put this file back in its original location?" }, { "Sélectionnez d'abord une ou plusieurs règles (Ctrl+clic).", "First select one or more rules (Ctrl+click)." }, { "Appliquer les règles du profil « recommandé » par la stratégie de groupe locale ?\n\nQuelques-unes changent l'usage du poste : le Bureau à distance est coupé (sauf s'il est activé sur ce poste : la règle est alors laissée de côté), un compte administrateur confirme chaque élévation sur le bureau sécurisé, et les partages réseau en accès invité (anciens NAS) ne sont plus accessibles.\n\nToutes sont réversibles (bouton Annuler).", "Apply the rules of the \"recommended\" profile through local group policy?\n\nA few of them change how the computer is used: Remote Desktop is turned off (unless it is enabled on this computer: that rule is then left out), an administrator account confirms each elevation on the secure desktop, and guest-access network shares (old NAS devices) can no longer be reached.\n\nAll of them can be reverted (Revert button)." }, { "Le profil « renforcé » peut gêner certains logiciels (voir la colonne Compatibilité).\n\nAppliquer quand même ?", "The \"hardened\" profile may hinder some software (see the Compatibility column).\n\nApply anyway?" }, { "Revenir aux valeurs d'origine pour les règles sélectionnées ?", "Go back to the original values for the selected rules?" }, { "Revenir aux valeurs d'origine pour toutes les règles « recommandé » et « renforcé » ?\n(La journalisation reste active.)", "Go back to the original values for every \"recommended\" and \"hardened\" rule?\n(Logging stays on.)" }, { "Caméra et micro", "Camera and microphone" }, { "Prise en main à distance", "Remote control" }, { "Ports ouverts", "Open ports" }, { "Exposition à Internet", "Internet exposure" }, { "Changements de règles", "Rule changes" }, { "Restaurer dans le dossier de deR4Tizer", "Restore to the deR4Tizer folder" },
